import { existsSync, readFileSync } from "node:fs";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import type { Tool } from "@modelcontextprotocol/sdk/types.js";

// ---------------------------------------------------------------------------
// Catalog (catalog/catalog.json, generated by scripts/gen-catalog.mjs)
// ---------------------------------------------------------------------------

export interface BackendSpec {
  id: string;
  // "<Vendor>" of the legacy "<Vendor>.Read" / "<Vendor>.Write" app roles.
  compatRole?: string;
  command: string;
  args: string[];
  envPrefixes: string[];
  // Keeps per-session state (Blumira's domain navigation): one child per user.
  stateful: boolean;
}

const ID_RE = /^[a-z0-9][a-z0-9_-]*$/;

function expand(value: string, backendsRoot: string): string {
  return value.replaceAll("${BACKENDS_ROOT}", backendsRoot);
}

export function parseCatalog(text: string, backendsRoot: string): BackendSpec[] {
  const doc = JSON.parse(text) as { version?: number; connectors?: unknown[] };
  if (doc.version !== 1 || !Array.isArray(doc.connectors)) throw new Error("catalog: expected version 1 with connectors[]");
  const seen = new Set<string>();
  return doc.connectors.map((raw, i) => {
    const c = raw as Record<string, unknown>;
    if (typeof c.id !== "string" || !ID_RE.test(c.id)) throw new Error(`catalog: connectors[${i}].id is invalid`);
    if (seen.has(c.id)) throw new Error(`catalog: duplicate connector id "${c.id}"`);
    seen.add(c.id);
    if (typeof c.command !== "string" || !Array.isArray(c.args) || !Array.isArray(c.envPrefixes)) {
      throw new Error(`catalog: connectors[${i}] (${c.id}) needs command, args and envPrefixes`);
    }
    return {
      id: c.id,
      compatRole: typeof c.compatRole === "string" ? c.compatRole : undefined,
      command: c.command === "node" ? process.execPath : expand(c.command, backendsRoot),
      args: (c.args as string[]).map((a) => expand(a, backendsRoot)),
      envPrefixes: c.envPrefixes as string[],
      stateful: c.stateful === true,
    };
  });
}

export function loadCatalog(path: string, backendsRoot: string): BackendSpec[] {
  return parseCatalog(readFileSync(path, "utf8"), backendsRoot);
}

// A connector is runnable when its entrypoint exists on disk, so a partial
// deploy (no falcon venv synced) does not crash the whole gateway.
export function isInstalled(spec: BackendSpec): boolean {
  const entry = spec.command === process.execPath ? spec.args[spec.args.length - 1] : spec.command;
  return entry !== undefined && existsSync(entry);
}

// ---------------------------------------------------------------------------
// Env allowlisting
// ---------------------------------------------------------------------------

// Least privilege: a connector child never sees another connector's secrets,
// so a bug in one vendor server cannot exfiltrate another vendor's keys.
const ALLOWED_COMMON_ENV = ["PATH", "HOME", "NODE_ENV", "TZ", "LANG", "SSL_CERT_FILE", "NODE_EXTRA_CA_CERTS"];

export function childEnv(spec: BackendSpec, env: NodeJS.ProcessEnv): Record<string, string> {
  const result: Record<string, string> = { MCP_TRANSPORT: "stdio" };
  for (const [key, value] of Object.entries(env)) {
    if (value === undefined) continue;
    const allowed = ALLOWED_COMMON_ENV.includes(key) || spec.envPrefixes.some((p) => key.startsWith(p));
    if (allowed) result[key] = value;
  }
  return result;
}

// ---------------------------------------------------------------------------
// Backend: a lazily-connected stdio MCP client for one connector child
// ---------------------------------------------------------------------------

export interface BackendLike {
  readonly spec: BackendSpec;
  listTools(): Promise<Tool[]>;
  callTool(name: string, args: Record<string, unknown> | undefined): Promise<unknown>;
  close(): Promise<void>;
}

export const CLIENT_INFO = { name: "mcp-gateway", version: "0.2.0" };

export class Backend implements BackendLike {
  readonly spec: BackendSpec;
  private client: Client | undefined;
  private connecting: Promise<Client> | undefined;

  constructor(spec: BackendSpec) {
    this.spec = spec;
  }

  private async connect(): Promise<Client> {
    if (this.client) return this.client;
    // Dedupe concurrent connects: two requests racing in share one spawn.
    if (this.connecting) return this.connecting;

    this.connecting = (async () => {
      const transport = new StdioClientTransport({
        command: this.spec.command,
        args: this.spec.args,
        env: childEnv(this.spec, process.env),
        stderr: "inherit",
      });
      const client = new Client(CLIENT_INFO);
      transport.onclose = () => {
        // The child exited or the pipe broke: the next use respawns.
        if (this.client === client) this.client = undefined;
      };
      await client.connect(transport);
      this.client = client;
      return client;
    })();

    try {
      return await this.connecting;
    } finally {
      this.connecting = undefined;
    }
  }

  async listTools(): Promise<Tool[]> {
    const client = await this.connect();
    const tools: Tool[] = [];
    let cursor: string | undefined;
    do {
      const page = await client.listTools(cursor ? { cursor } : undefined);
      tools.push(...page.tools);
      cursor = page.nextCursor;
    } while (cursor);
    return tools;
  }

  async callTool(name: string, args: Record<string, unknown> | undefined): Promise<unknown> {
    const client = await this.connect();
    return client.callTool({ name, arguments: args });
  }

  async close(): Promise<void> {
    const client = this.client;
    this.client = undefined;
    if (client) await client.close();
  }
}

// ---------------------------------------------------------------------------
// Pool: one shared child per stateless connector, one child per user for
// stateful connectors, reaped after an idle timeout and capped in number.
// ---------------------------------------------------------------------------

export type BackendFactory = (spec: BackendSpec) => BackendLike;

export interface PoolOptions {
  idleMs: number;
  maxPerUserChildren: number;
  now?: () => number;
}

interface PerUserEntry {
  backend: BackendLike;
  lastUsed: number;
}

export class BackendPool {
  readonly specs: readonly BackendSpec[];
  private readonly factory: BackendFactory;
  private readonly opts: Required<PoolOptions>;
  private readonly shared = new Map<string, BackendLike>();
  private readonly perUser = new Map<string, PerUserEntry>();

  constructor(specs: readonly BackendSpec[], factory: BackendFactory, opts: PoolOptions) {
    this.specs = specs;
    this.factory = factory;
    this.opts = { now: Date.now, ...opts };
  }

  spec(id: string): BackendSpec | undefined {
    return this.specs.find((s) => s.id === id);
  }

  // userKey is the stable subject (issuer + sub), never a display name.
  get(connectorId: string, userKey: string): BackendLike {
    const spec = this.spec(connectorId);
    if (!spec) throw new Error(`unknown connector ${connectorId}`);
    if (!spec.stateful) {
      let b = this.shared.get(spec.id);
      if (!b) {
        b = this.factory(spec);
        this.shared.set(spec.id, b);
      }
      return b;
    }
    const key = `${spec.id}\u0000${userKey}`;
    const now = this.opts.now();
    const existing = this.perUser.get(key);
    if (existing) {
      existing.lastUsed = now;
      return existing.backend;
    }
    this.evictForCapacity();
    const entry = { backend: this.factory(spec), lastUsed: now };
    this.perUser.set(key, entry);
    return entry.backend;
  }

  // A child outside the pool's bookkeeping, for startup discovery of a
  // stateful connector's tool list. The caller closes it.
  transient(connectorId: string): BackendLike {
    const spec = this.spec(connectorId);
    if (!spec) throw new Error(`unknown connector ${connectorId}`);
    return this.factory(spec);
  }

  perUserCount(): number {
    return this.perUser.size;
  }

  // Least recently used goes first when the cap is reached.
  private evictForCapacity(): void {
    while (this.perUser.size >= this.opts.maxPerUserChildren) {
      let oldestKey: string | undefined;
      let oldest = Infinity;
      for (const [k, e] of this.perUser) {
        if (e.lastUsed < oldest) {
          oldest = e.lastUsed;
          oldestKey = k;
        }
      }
      if (oldestKey === undefined) return;
      const e = this.perUser.get(oldestKey)!;
      this.perUser.delete(oldestKey);
      void e.backend.close().catch(() => undefined);
    }
  }

  async reapIdle(): Promise<number> {
    const cutoff = this.opts.now() - this.opts.idleMs;
    const victims = [...this.perUser.entries()].filter(([, e]) => e.lastUsed < cutoff);
    for (const [k] of victims) this.perUser.delete(k);
    await Promise.allSettled(victims.map(([, e]) => e.backend.close()));
    return victims.length;
  }

  async closeAll(): Promise<void> {
    const all = [...this.shared.values(), ...[...this.perUser.values()].map((e) => e.backend)];
    this.shared.clear();
    this.perUser.clear();
    await Promise.allSettled(all.map((b) => b.close()));
  }
}
